change_filament_gcode:
{if total_toolchanges == 0 and current_extruder == 1}
  ;===== 首次切换至 T1 时 =====
  ; 保持 T0 待机温度，防止冷卻堵塞
  M104 T0 S{idle_temperature[0]}

{elsif total_toolchanges > 0 and current_extruder == 0}
  ;===== 从 T0 切换到 T1 流程 =====
  ; 1. 设置非活动喷头（T0）的待机温度
  M104 T0 S{idle_temperature[0]}
  ; 2. 执行回抽防止渗料
  G91                ; 切换到相对坐标模式
  G1 E-1.0 F2400     ; 回抽1.0mm（速度40mm/s）<<< 修改点
  G90                ; 恢复绝对坐标模式
  ; 3. 切换至T1并等待温度达标
  T1                 ; 切换喷头命令
  {if layer_z == initial_layer_print_height}
    M109 S{nozzle_temperature_initial_layer[1]} T1  ; T1首层温度
  {else}
    M109 S{nozzle_temperature[1]} T1               ; T1正常层温度
  {endif}

{elsif total_toolchanges > 0 and current_extruder == 1}
  ;===== 从 T1 切换到 T0 流程 =====
  ; 1. 设置非活动喷头（T1）的待机温度
  M104 T1 S{idle_temperature[1]}
  ; 2. 执行回抽防止渗料
  G91                ; 切换到相对坐标模式
  G1 E-1.0 F2400     ; 回抽1.0mm（速度40mm/s）<<< 修改点
  G90                ; 恢复绝对坐标模式
  ; 3. 切换至T0并等待温度达标
  T0                 ; 切换喷头命令
  {if layer_z == initial_layer_print_height}
    M109 S{nozzle_temperature_initial_layer[0]} T0  ; T0首层温度
  {else}
    M109 S{nozzle_temperature[0]} T0               ; T0正常层温度
  {endif}
{endif}
